import java.util.*;
import java.io.*;

public class Main {
    static long[] countShortest(int n, int[][] edges, int s, int t) {
        // Write your solution here
        // Return {distance, number of shortest paths mod 1000000007}; {-1, 0} if t is unreachable.
        return new long[]{-1, 0};
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        int[][] edges = new int[m][2];
        for (int i = 0; i < m; i++) {
            in.nextToken(); edges[i][0] = (int) in.nval;
            in.nextToken(); edges[i][1] = (int) in.nval;
        }
        in.nextToken();
        int s = (int) in.nval;
        in.nextToken();
        int t = (int) in.nval;
        long[] res = countShortest(n, edges, s, t);
        System.out.println(res[0] + " " + res[1]);
    }
}
